from typing import Any

from orders.application.errors import OrderNotFound
from orders.application.fulfilment_service import FulfilmentService
from orders.controllers.http import Response, not_found, conflict


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            slip = self._service.get_packing_slip(order_id)
        except OrderNotFound:
            return not_found("order")
        order = self._service._orders.get(order_id)
        if order.status == "cancelled":
            return conflict(OrderCancelledError(order_id))
        return Response(200, {
            "order_id": slip.order_id,
            "customer_name": slip.customer_name,
            "lines": slip.lines,
        })


class OrderCancelledError(Exception):
    def __init__(self, order_id: str) -> None:
        super().__init__(f"order {order_id} is cancelled")

